package com.growth360.model;

/**
 * Record representing an actionable recommendation generated by the Prescriptive Recommendation Engine.
 */
public record Recommendation(
        String id,
        String alertId,
        String category,
        String title,
        String actionText,
        Priority priority,
        String expectedImpact
) {
    public enum Priority {
        LOW,
        MEDIUM,
        HIGH,
        URGENT
    }
}
